// Social-Pip Instagram Pre-Publish Check
const item = $input.first().json;

// Anti-ban: Instagram specific limits
const INSTAGRAM_MAX_DAILY = 5;
const INSTAGRAM_MIN_DELAY_MS = 45 * 60 * 1000; // 45 minutes
const INSTAGRAM_MAX_HASHTAGS = 30;
const INSTAGRAM_MAX_CHARS = 2200;

const accountStats = {
  postsToday: item.postsToday || 0,
  lastPostAt: item.lastPostAt ? new Date(item.lastPostAt) : null,
  accountStatus: item.accountStatus || 'ACTIVE'
};

const errors = [];

// Check daily limit (more restrictive than Facebook)
if (accountStats.postsToday >= INSTAGRAM_MAX_DAILY) {
  errors.push(`Daily limit reached: ${accountStats.postsToday}/${INSTAGRAM_MAX_DAILY}`);
}

// Check delay
if (accountStats.lastPostAt) {
  const timeSinceLastPost = Date.now() - accountStats.lastPostAt.getTime();
  if (timeSinceLastPost < INSTAGRAM_MIN_DELAY_MS) {
    const waitMinutes = Math.ceil((INSTAGRAM_MIN_DELAY_MS - timeSinceLastPost) / 60000);
    errors.push(`Too soon. Wait ${waitMinutes} more minutes.`);
  }
}

// Check account status
if (['BANNED', 'RESTRICTED', 'COOLDOWN'].includes(accountStats.accountStatus)) {
  errors.push(`Account status: ${accountStats.accountStatus}`);
}

// Instagram-specific: Check content
if (item.content) {
  if (item.content.length > INSTAGRAM_MAX_CHARS) {
    errors.push(`Content too long: ${item.content.length}/${INSTAGRAM_MAX_CHARS}`);
  }

  const hashtags = (item.content.match(/#/g) || []).length;
  if (hashtags > INSTAGRAM_MAX_HASHTAGS) {
    errors.push(`Too many hashtags: ${hashtags}/${INSTAGRAM_MAX_HASHTAGS}`);
  }
}

if (errors.length > 0) {
  return { json: { valid: false, errors, accountStats } };
}

return { json: { valid: true, post: item, accountStats } };

const result = $input.first().json;

if (result.error) {
  return {
    json: {
      success: false,
      error: result.error,
      errorCode: result.errorCode || 'UNKNOWN',
      platform: 'instagram'
    }
  };
}

return {
  json: {
    success: true,
    postId: result.id,
    postUrl: `https://instagram.com/p/${result.code}`,
    publishedAt: new Date().toISOString(),
    platform: 'instagram'
  }
};
